/// O(1) glyph metric for `code` in a Computer Modern face (`None` outside 0..128 or for
/// faces without TFM data).
#[inline]
pub fn cm_face_metric(face: Face, code: u8) -> Option<GlyphMetric> {
    if code >= 128 {
        return None;
    }
    cm_face_table(face).map(|t| t[code as usize].unpack())
}

/// Whether `face` is one of the math-alphabet faces added on top of the original CM set
/// (each has its own TFM table here and its own embedded Type 1C program).
#[inline]
pub const fn is_alphabet_face(face: Face) -> bool {
    ((face as u8) >= Face::MathSans as u8 && (face as u8) <= Face::Extension7 as u8) || (face as u8) >= Face::MathItalic6 as u8
}

/// Whether a math-alphabet face is a text font (TFM `space` != 0: cmss, cmtt, eufm). TeX's
/// `make_ord` then drops the italic correction between consecutive letters of one word
/// (`math_text_char`, tex.web §752/§755).
#[inline]
pub const fn is_text_font_face(face: Face) -> bool {
    matches!(
        face,
        Face::Mono | Face::MathMono8 | Face::MathSans | Face::MathSans8 | Face::Fraktur | Face::Fraktur7 | Face::Fraktur5
    )
}

/// TFM kern in points at `size` between two letters of one math-alphabet face, exact
/// (`store_scaled`, §571); 0 for faces whose kern programs have no letter pairs (cmtt, eufm).
#[inline]
pub fn cm_face_kern(face: Face, left: u8, right: u8, size: f32) -> f32 {
    let table = match face {
        Face::MathSans => &CMSS10_KERNS,
        Face::MathSans8 => &CMSS8_KERNS,
        Face::BoldMathItalic => &CMMIB10_KERNS,
        Face::BoldMathItalic7 => &CMMIB7_KERNS,
        Face::BoldMathItalic5 => &CMMIB5_KERNS,
        _ => return 0.0,
    };
    crate::backend::scaled::Scaler::at_pt(size).scale(table.kern_fix(left, right)) as f32 / 65536.0
}

