#[cfg(test)]
mod tests {
    use super::*;

    fn pt(v: f32, size: f32) -> f32 {
        v * size * 0.001
    }

    #[test]
    fn alphabet_tables_match_tfm_reference_values() {
        // pdfLaTeX \wd/\ht/\dp of single glyphs (10pt CM, amsmath), within TFM rounding.
        let s = cm_face_metric(Face::MathSans, b's').unwrap();
        assert!((pt(s.w, 10.0) - 3.833).abs() < 0.01 && (pt(s.h, 10.0) - 4.444).abs() < 0.01);
        let t = cm_face_metric(Face::Mono, b't').unwrap();
        assert!((pt(t.w, 10.0) - 5.250).abs() < 0.01 && (pt(t.h, 10.0) - 5.536).abs() < 0.01);
        let l = cm_face_metric(Face::Symbol, b'L').unwrap();
        assert!((pt(l.w + l.ic, 10.0) - 6.897).abs() < 0.01);
        let g = cm_face_metric(Face::Fraktur, b'g').unwrap();
        assert!((pt(g.w, 10.0) - 5.037).abs() < 0.01);
        assert!((pt(g.h, 10.0) - 4.753).abs() < 0.01 && (pt(g.d, 10.0) - 1.891).abs() < 0.01);
        let a = cm_face_metric(Face::BoldMathItalic, 0x0B).unwrap();
        assert!((pt(a.w + a.ic, 10.0) - 7.606).abs() < 0.01 && (pt(a.h, 10.0) - 4.444).abs() < 0.01);
        // cmex7 text summation is 1.2em of 7pt (8.403pt).
        let sum = cm_face_metric(Face::Extension7, 0x50).unwrap();
        assert!((pt(sum.w, 7.0) - 8.403).abs() < 0.01);
        // Script sizes come from the 8pt designs (LaTeX <5-8> cmss8 / cmtt8).
        let s8 = cm_face_metric(Face::MathSans8, b's').unwrap();
        assert!((pt(s8.w, 7.0) - 2.851).abs() < 0.01);
        let t8 = cm_face_metric(Face::MathMono8, b't').unwrap();
        assert!((pt(t8.h, 7.0) - 3.875).abs() < 0.01);
    }

    #[test]
    fn every_cm_face_with_tfm_data_resolves() {
        for &f in Face::ALL.iter() {
            let has = cm_face_table(f).is_some();
            assert_eq!(has, !matches!(f, Face::BoldItalic | Face::MonoBold | Face::Dingbats), "{f:?}");
        }
        assert!(cm_face_metric(Face::Fraktur, 200).is_none());
        assert!(is_alphabet_face(Face::Fraktur7) && !is_alphabet_face(Face::AmsB));
    }

    #[test]
    fn alphabet_kerns_and_text_font_rule() {
        // cmss10: w-o and o-r kern -0.0278em; d-f none.
        assert!((cm_face_kern(Face::MathSans, b'w', b'o', 1.0) + 0.0278).abs() < 1e-4);
        assert!((cm_face_kern(Face::MathSans, b'o', b'r', 1.0) + 0.0278).abs() < 1e-4);
        assert_eq!(cm_face_kern(Face::Mono, b'A', b'V', 10.0), 0.0);
        assert!(is_text_font_face(Face::MathSans8) && is_text_font_face(Face::Fraktur));
        assert!(!is_text_font_face(Face::BoldMathItalic) && !is_text_font_face(Face::Symbol));
    }

    #[test]
    fn alphabet_layout_matches_pdflatex_boxes() {
        use crate::backend::fonts::FontFamily;
        use crate::math::math_ast::MathStyle;
        // (formula, pdfLaTeX \wd, \ht, \dp) at 10pt Computer Modern with amsmath.
        let cases: [(&str, f32, f32, f32); 12] = [
            (r"\mathsf{word}", 19.861, 6.944, 0.0),
            (r"\mathtt{code}", 21.000, 6.111, 0.0),
            (r"\mathcal{ABC}", 20.706, 6.833, 0.0),
            (r"\mathfrak{gl}", 7.832, 6.914, 1.891),
            (r"\boldsymbol{xy}", 12.863, 4.444, 1.944),
            (r"\boldsymbol{\nabla}", 9.583, 6.861, 0.0),
            (r"\boldsymbol{f}^2", 11.271, 8.983, 1.944),
            (r"{\scriptstyle \mathsf{Hello}}", 15.823, 4.861, 0.0),
            (r"{\scriptstyle \mathfrak{su}}", 8.085, 3.330, 0.0),
            (r"{\scriptscriptstyle \boldsymbol{\alpha}}", 5.150, 2.222, 0.0),
            // Latin Modern's lmex10 is `sfixed`: the 10pt operator in script style too.
            (r"{\scriptstyle \sum}", 10.556, 6.750, 3.250),
            (r"{\scriptscriptstyle \mathtt{t}}", 2.656, 2.768, 0.0),
        ];
        for (src, w, h, d) in cases {
            let node = crate::math::math_parser::parse_math_str(src);
            let b = crate::math::math_layout::measure_math(&node, 10.0, FontFamily::ComputerModern, MathStyle::Text);
            assert!(
                (b.w - w).abs() < 0.02 && (b.h - h).abs() < 0.02 && (b.d - d).abs() < 0.02,
                "{src}: got {} {} {}, want {w} {h} {d}",
                b.w,
                b.h,
                b.d
            );
        }
    }

    #[test]
    fn alphabet_tables_fit_cache_lines() {
        assert_eq!(core::mem::size_of_val(&CMSS10_METRICS), 1024);
        assert_eq!(core::mem::size_of_val(&super::super::math_tfm::CMR10_METRICS), 1024);
    }
}
